//! The `__name__` handler is registered at `__path__` (generated by
//! `engine generate handler`). To drive it over HTTP against a throwaway
//! database, see "Testing an app crate" in the "App crates" docs.

use std::process::Command;

use engine_cli::serde_json::{self, Value};

#[test]
fn __module___is_registered() {
    let out = Command::new(env!("CARGO_BIN_EXE___bin__"))
        .args(["routes", "--json", "--site", env!("CARGO_MANIFEST_DIR")])
        .output()
        .unwrap();
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    let list: Value = serde_json::from_slice(&out.stdout).unwrap();
    let found = list["routes"].as_array().unwrap().iter().any(|r| {
        r["kind"] == "handler" && r["path"] == "__path__" && r["methods"][0] == "__METHOD__"
    });
    assert!(found, "{list:#}");
}
